"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[968],{70968:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/bat.png\\"\\n          title=\\"박쥐\\"\\n          author=\\"요 네스뵈\\"\\n          publisher=\\"비채\\"\\n          publishedDate=\\"2014-02-27\\"\\n          isbn=\\"9791185014449\\"\\n          rating=3.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n해리 홀레 시리즈 중 <mark>스노우맨</mark>이라는 작품이 재미있다고 해서, 어쩔 수 없이 해리 홀레 시리즈 1부터 봤다.  \\n```해리 홀레``` 형사의 캐릭터에 대한 묘사와 과거 이야기들이 조금씩 나온다.  \\n알코올 의존증이 있고 ```흔들리는 젋은 형사```로 표현되며 독자들에게 매력적인 인물로 그려진다.  \\n아마 시리즈를 하나하나 발표하며 캐릭터가 더욱 탄탄해지고 분명해져 이 시리즈가 많은 사랑을 받은 것 같다.  \\n<br>\\n전형적인 서양 스릴러 느낌이 물씬 풍긴다.  \\n범인에 대한 반전이 있지만, 너무 갑작스럽고 복선이 좀 약한 것 아닌가 싶다.  \\n더 많은 떡밥이 있었으면 어땠을까?\\n<br>\\n이후 시리즈도 모두 구매하긴 했다."}')}}]);